SourceCode.Declaration:
/// <summary>
/// Class for validating DMF contracts
/// </summary>
class OMGContractValidator_DMF
{
    OMGInboundHandlerDataContract_DMF   dataContract;

}

Method.Source:
public OMGInboundHandlerDataContract_DMF parmDataContract(OMGInboundHandlerDataContract_DMF _dataContract = dataContract)
{
    dataContract = _dataContract;
    return dataContract;
}

/// <summary>
/// Instantiates the class and sets the datacontract
/// </summary>
/// <param name = "_dataContract">The data contract</param>
/// <returns>The instantiated class</returns>
public static OMGContractValidator_DMF newValidation(OMGInboundHandlerDataContract_DMF    _dataContract)
{
    SysDictClass                sysDictValidationClass = new SysDictClass(_dataContract.validationClassId());
    OMGContractValidator_DMF    contractValidator_DMF;
    ;

    if (sysDictValidationClass)
    {
        contractValidator_DMF = sysDictValidationClass.makeObject();
        contractValidator_DMF.parmDataContract(_dataContract);
    }

    return contractValidator_DMF;
}

/// <summary>
/// Validates the DMF setup
/// </summary>
/// <returns>True if all ok</returns>
public boolean validate()
{
    boolean     ret = this.validateDefinitionGroup();

    if (ret)
    {
        ret = this.validateDefinitionGroupEntity();
    }

    return ret;
}

/// <summary>
/// Validate the DMF definition group
/// </summary>
/// <returns>True if exists</returns>
protected boolean validateDefinitionGroup()
{
    boolean ret = true;

    if (!DMFDefinitionGroup::find(dataContract.parmDefinitionGroupName()).RecId)
    {
        ret = checkFailed(strFmt("@OMG:ImportProjectDoesntExist", dataContract.parmDefinitionGroupName()));
    }
    return ret;
}

/// <summary>
/// Validate the DMF definition group
/// </summary>
/// <returns>True if exists</returns>
protected boolean validateDefinitionGroupEntity()
{
    boolean ret = true;

    if (!DMFDefinitionGroupEntity::find(dataContract.parmDefinitionGroupName(), dataContract.parmEntityName()).RecId)
    {
        ret = checkFailed(strFmt("@OMG:ImportEntityDoesntExist", dataContract.parmEntityName()));
    }
    return ret;
}
